<script setup>
import {computed,ref,onMounted,nextTick} from 'vue'
import {Headphones,LayoutDashboard,History,ShieldCheck,ArrowUpRight,ArrowRight,ArrowLeft,Play,Send,Check,CheckCheck,ChevronRight,BookOpen,Package,MessagesSquare,RefreshCw,LogOut,AlertCircle,LoaderCircle,Square,Target,TrendingUp,FileCheck,Clock,ExternalLink,GraduationCap,Search,CheckCircle2} from 'lucide-vue-next'
import {api,post,streamMessage} from './api'
const view=ref('home'),health=ref(null),scenarios=ref([]),records=ref([]),session=ref(null),report=ref(null),comparison=ref(null)
const error=ref(''),loading=ref(false),sending=ref(false),evaluating=ref(false),draft=ref(''),partial=ref(''),chatEl=ref(null),activeTab=ref('order')
const documents=ref({}),admin=ref(null),adminToken=ref(sessionStorage.getItem('admin-token')||''),adminLoading=ref(false)
const policyQuery=ref(''),retrieved=ref(null)
let controller=null
const labels={facts:'사실 확인',policy:'정책 준수',solution:'해결안',communication:'의사소통'}
const tabs=[{key:'order',label:'주문',icon:Package},{key:'history',label:'상담 이력',icon:MessagesSquare},{key:'policy',label:'회사 정책',icon:BookOpen}]
const locked=computed(()=>sending.value||evaluating.value||loading.value)
const completed=computed(()=>records.value.filter(x=>x.total!==null))
const average=computed(()=>completed.value.length?Math.round(completed.value.reduce((s,x)=>s+x.total,0)/completed.value.length):'—')
const currentScenario=computed(()=>scenarios.value.find(x=>x.id===session.value?.scenario_id))
const turns=computed(()=>session.value?.messages.filter(x=>x.role==='user').length||0)
const policyList=computed(()=>documents.value.policy||[])
const fmtDate=s=>new Date(s).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})
const delta=n=>(n>0?'+':'')+n
async function scrollChat(){await nextTick();if(chatEl.value)chatEl.value.scrollTop=chatEl.value.scrollHeight}
function setSession(s){session.value=s;documents.value={};retrieved.value=null;policyQuery.value='';for(const r of s.lookups||[]){if(r.actor==='trainee'){if(r.tool==='search_policy'){retrieved.value=r.result;documents.value.policy=r.result.hits}else documents.value[r.tool.replace('get_','')]=r.result}}localStorage.setItem('rehearsal-session',s.id)}
async function refreshHistory(){records.value=await api('/sessions')}
async function boot(){error.value='';try{[health.value,scenarios.value]=await Promise.all([api('/health'),api('/scenarios')]);await refreshHistory();const id=localStorage.getItem('rehearsal-session');if(id){try{const s=await api('/sessions/'+id);if(s.status==='active'){setSession(s);view.value='training';scrollChat()}}catch{localStorage.removeItem('rehearsal-session')}}}catch(e){error.value='서버에 연결할 수 없습니다. Python 서버 실행 상태를 확인해 주세요.'}}
onMounted(boot)
async function start(id){if(locked.value)return;loading.value=true;error.value='';try{setSession(await post('/sessions',{scenario_id:id}));draft.value='';partial.value='';view.value='training';await refreshHistory();scrollChat()}catch(e){error.value=e.message}finally{loading.value=false}}
async function openRecord(id){if(locked.value)return;loading.value=true;error.value='';try{const s=await api('/sessions/'+id);setSession(s);draft.value='';if(s.report){report.value=s.report;comparison.value=await api(`/sessions/${id}/comparison`);view.value='report'}else{view.value='training';scrollChat()}}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadDoc(kind){if(locked.value||!session.value)return;activeTab.value=kind;loading.value=true;error.value='';try{const result=await post(`/sessions/${session.value.id}/lookup/${kind}`);documents.value[kind]=result.data;session.value=await api('/sessions/'+session.value.id)}catch(e){error.value=e.message}finally{loading.value=false}}
async function searchPolicy(){if(locked.value||!session.value||!policyQuery.value.trim())return;loading.value=true;error.value='';try{const result=await post(`/sessions/${session.value.id}/policy-search`,{query:policyQuery.value,top_k:4});retrieved.value=result;documents.value.policy=result.hits;session.value=await api('/sessions/'+session.value.id)}catch(e){error.value=e.message}finally{loading.value=false}}
async function send(){const text=draft.value.trim();if(!text||locked.value||turns.value>=20)return;error.value='';sending.value=true;draft.value='';partial.value='';controller=new AbortController();const id=session.value.id
  try{const result=await streamMessage(id,text,chunk=>{partial.value+=chunk;scrollChat()},controller.signal);session.value.messages.push(result.user_message,result.message)}
  catch(e){error.value=e.name==='AbortError'?'응답을 중단했습니다. 저장된 대화를 확인한 뒤 다시 시도하세요.':e.message;try{session.value=await api('/sessions/'+id);if(session.value.messages.at(-2)?.content!==text)draft.value=text}catch{draft.value=text}}
  finally{partial.value='';sending.value=false;controller=null;scrollChat()}}
async function finish(){if(locked.value||!turns.value)return;evaluating.value=true;error.value='';try{const s=await post(`/sessions/${session.value.id}/finish`);setSession(s);report.value=s.report;comparison.value=await api(`/sessions/${s.id}/comparison`);view.value='report';await refreshHistory()}catch(e){error.value=e.message;try{session.value=await api('/sessions/'+session.value.id)}catch{}}finally{evaluating.value=false}}
async function retry(){if(locked.value)return;loading.value=true;error.value='';try{setSession(await post(`/sessions/${session.value.id}/retry`));draft.value='';view.value='training';await refreshHistory();scrollChat()}catch(e){error.value=e.message}finally{loading.value=false}}
async function go(where){if(locked.value)return;view.value=where;error.value='';if(where==='history'||where==='home')try{await refreshHistory()}catch(e){error.value=e.message}}
async function loadAdmin(){adminLoading.value=true;error.value='';try{admin.value=await api('/admin/overview',{headers:{'X-Admin-Token':adminToken.value}});sessionStorage.setItem('admin-token',adminToken.value)}catch(e){admin.value=null;error.value=e.message}finally{adminLoading.value=false}}
const pendingText=computed(()=>sending.value?partial.value||'고객이 답변을 작성하고 있어요…':'')
</script>

<template>
<div class="app-shell">
  <aside class="sidebar">
    <button class="brand" @click="go('home')" :disabled="locked"><span class="brand-mark"><Headphones :size="22"/></span><span>응대 리허설<small>TEAM TRAINING WORKSPACE</small></span></button>
    <div class="workspace"><span class="workspace-icon">R</span><div>리허설 아카데미<small>고객 경험 교육 워크스페이스</small></div><span class="workspace-dot"></span></div>
    <div class="nav-label">WORKSPACE</div>
    <nav>
      <button :class="{active:view==='home'}" @click="go('home')" :disabled="locked"><LayoutDashboard :size="19"/>훈련 대시보드</button>
      <button v-if="session && !session.report" :class="{active:view==='training'}" @click="go('training')" :disabled="locked"><MessagesSquare :size="19"/>진행 중인 상담<span class="tiny-dot"></span></button>
      <button :class="{active:view==='history'||view==='report'}" @click="go('history')" :disabled="locked"><History :size="19"/>훈련 기록<span class="nav-count">{{completed.length}}</span></button>
      <button :class="{active:view==='admin'}" @click="go('admin')" :disabled="locked"><ShieldCheck :size="19"/>관리자</button>
    </nav>
    <div class="sidebar-tip"><GraduationCap :size="26"/><strong>실수해도 괜찮은 곳</strong><p>어려운 상담도, 반복하면<br>나만의 응대가 됩니다.</p><div class="tip-line"></div><span>확인하고 · 설명하고 · 다시 연습하기</span></div>
    <div class="profile"><div class="avatar purple">나</div><div><strong>훈련생</strong><small>상담 역량을 쌓는 중</small></div><span class="online-dot"></span></div>
  </aside>

  <main class="main">
    <header class="topbar"><div class="breadcrumb">워크스페이스 <ChevronRight :size="14"/><strong>{{({home:'훈련 대시보드',training:'상담 연습',history:'훈련 기록',report:'훈련 리포트',admin:'관리자'})[view]}}</strong></div><div class="topbar-right"><span :class="['mode-pill',health?.mode==='demo'?'demo':'']"><span></span>{{health?.mode==='openai'?'OpenAI 연결 모드':health?.mode==='demo'?'데모 모드':'연결 확인 중'}}</span><span class="top-avatar">나</span></div></header>
    <div v-if="error" class="error-banner" role="alert"><AlertCircle :size="18"/><span>{{error}}</span><button @click="error=''" aria-label="오류 닫기">×</button></div>
    <div v-if="health?.mode==='demo'" class="demo-banner">데모 모드에서는 정해진 반응과 단순 규칙으로 평가합니다. 실제 AI 훈련은 OpenAI 모드로 실행해 주세요.</div>

    <section v-if="view==='home'" class="page dashboard">
      <div class="page-heading"><div><div class="eyebrow">PRACTICE MAKES CONFIDENT</div><h1>좋은 응대는, 연습에서 시작돼요.</h1><p>까다로운 고객을 만나도 흔들리지 않도록. 오늘의 상담을 미리 연습해 보세요.</p></div><div class="date-badge"><Clock :size="16"/>한 번에 5–10분</div></div>
      <div class="stats-row">
        <div class="stat-card"><div class="stat-icon lavender"><CheckCheck :size="22"/></div><div><span>완료한 훈련</span><strong>{{completed.length}}<small>회</small></strong></div><span class="stat-note">차곡차곡 쌓이는 경험</span></div>
        <div class="stat-card"><div class="stat-icon mint"><Target :size="22"/></div><div><span>평균 평가 점수</span><strong>{{average}}<small>/ 100</small></strong></div><span class="stat-note">내 응대의 현재 위치</span></div>
        <div class="stat-card"><div class="stat-icon peach"><TrendingUp :size="22"/></div><div><span>재도전한 훈련</span><strong>{{records.filter(x=>x.retry_of).length}}<small>회</small></strong></div><span class="stat-note">어제보다 나은 한 번</span></div>
      </div>
      <div class="hero-card"><div><span class="hero-label"><span></span>오늘의 추천 훈련</span><h2>“어제는 된다고 했잖아요.”<br>이 한마디에, 어떻게 답할까요?</h2><p>주문과 이전 상담을 확인하고, 정책 안에서 해결책을 찾아보세요.<br>상담이 끝나면 근거가 있는 피드백이 기다리고 있어요.</p><button class="primary light" @click="start('delivery')" :disabled="locked||!health">배송 지연 상담 연습하기 <ArrowUpRight :size="18"/></button></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-bubble bubble-a"><span>고객</span>지금 당장 해결해 주세요!<span class="bubble-tail"></span></div><div class="art-bubble bubble-b"><span class="check-disc"><Check :size="17"/></span><div>사실 확인부터, 차분하게.<small>내일의 자신감을 연습해요</small></div></div><div class="headphone-art"><Headphones :size="98" :stroke-width="1.4"/></div><span class="art-spark spark-one">✧</span><span class="art-spark spark-two">✧</span></div></div>
      <div class="section-heading"><div><h2>어떤 상담을 연습할까요?</h2><p>실제 업무에서 만날 법한 상황으로 준비했어요.</p></div><span class="muted">3가지 실전 시나리오</span></div>
      <div class="scenario-grid"><article v-for="(s,i) in scenarios" :key="s.id" class="scenario-card"><div class="scenario-top"><span class="scenario-icon" :style="{background:s.color+'15',color:s.color}"><Package v-if="i===0" :size="25"/><RefreshCw v-else-if="i===1" :size="25"/><MessagesSquare v-else :size="25"/></span><span class="difficulty">{{s.difficulty}}</span></div><span class="scenario-subtitle">{{s.subtitle}}</span><h3>{{s.title}}</h3><p>{{s.brief}}</p><div class="scenario-footer"><span><Clock :size="14"/>{{s.minutes}}</span><button @click="start(s.id)" :disabled="locked">훈련 시작 <ArrowRight :size="16"/></button></div></article></div>
      <div class="section-heading"><div><h2>최근 훈련 기록</h2><p>지난 상담을 돌아보고, 같은 상황에 다시 도전하세요.</p></div><button class="text-btn" @click="go('history')">전체 보기 <ArrowRight :size="15"/></button></div>
      <div v-if="!records.length" class="empty compact"><FileCheck :size="30"/><strong>첫 번째 훈련을 시작해 보세요.</strong><p>완료한 상담과 피드백이 여기에 모여요.</p></div>
      <div v-else class="record-list"><button v-for="r in records.slice(0,3)" :key="r.id" @click="openRecord(r.id)" class="record-row"><div class="record-symbol"><MessagesSquare :size="19"/></div><div class="record-main"><strong>{{r.title}}</strong><small>{{fmtDate(r.created_at)}} · {{r.mode==='demo'?'데모':'AI 훈련'}}{{r.retry_of?' · 재도전':''}}</small></div><span :class="['status',r.status==='completed'?'complete':'']">{{r.status==='completed'?'평가 완료':r.status==='evaluating'?'평가 중':'진행 중'}}</span><strong class="record-score">{{r.total===null?'—':r.total+'점'}}</strong><ChevronRight :size="17"/></button></div>
    </section>

    <section v-else-if="view==='training'&&session" class="training-page">
      <div class="training-heading"><div><div class="eyebrow">LIVE REHEARSAL <span class="live-dot"></span></div><h1>{{session.title}}</h1><p>{{currentScenario?.subtitle}} <span>· {{turns}} / 20턴</span></p></div><button class="primary" @click="finish" :disabled="locked||!turns"><LoaderCircle v-if="evaluating" class="spin" :size="17"/><FileCheck v-else :size="17"/>{{evaluating?'평가·코칭 중…':'상담 종료하고 평가받기'}}</button></div>
      <div class="training-grid">
        <aside class="brief-panel panel"><span class="panel-kicker">YOUR MISSION</span><h3>오늘의 상담 상황</h3><p>{{currentScenario?.brief}}</p><div class="brief-divider"></div><span class="panel-kicker">CHECKLIST</span><ol class="checklist"><li v-for="t in tabs" :key="t.key" :class="{checked:documents[t.key]}"><span><Check v-if="documents[t.key]" :size="13"/><span v-else>·</span></span>{{t.label}} 확인</li><li><span>·</span>가능한 해결안 설명</li><li><span>·</span>다음 절차와 일정 안내</li></ol><div class="mission-tip"><BookOpen :size="18"/><p>고객의 요구를 모두 수용하기보다, 확인한 사실과 정책을 근거로 설명해 보세요.</p></div><div v-if="session.retry_of" class="retry-label"><RefreshCw :size="15"/>같은 상황에 재도전 중</div><div class="brief-bottom"><ShieldCheck :size="17"/><span>실제 주문이나 환불은<br>처리되지 않는 훈련입니다.</span></div></aside>
        <div class="chat-panel panel"><div class="chat-header"><div class="avatar peach"><Headphones :size="21"/></div><div><strong>AI 고객</strong><small><span class="online-dot"></span>{{sending?'답변 작성 중':'상담 연결됨'}}</small></div><span class="chat-type">{{health?.mode==='demo'?'데모 고객':'까다로운 고객'}}</span></div><div class="chat-body" ref="chatEl" aria-live="polite"><div class="chat-date">안전하게 연습하는 상담 공간</div><div v-for="m in session.messages" :key="m.id" :class="['message',m.role==='user'?'mine':'customer']"><div v-if="m.role!=='user'" class="message-avatar">고</div><div class="message-content"><span class="message-name">{{m.role==='user'?'나 · 상담사':'AI 고객'}}</span><div class="message-bubble">{{m.content}}</div><span class="message-time">{{new Date(m.created_at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}}</span></div></div><div v-if="sending" class="message customer"><div class="message-avatar">고</div><div class="message-content"><span class="message-name">AI 고객</span><div class="message-bubble streaming">{{pendingText}}<span class="typing-cursor"></span></div></div></div><div v-if="evaluating" class="evaluation-progress"><LoaderCircle class="spin" :size="20"/><strong>상담 내용을 검토하고 있어요.</strong><span>업무 근거 확인 → 항목별 평가 → 개선 답변 작성<br>모델에 따라 수 분이 걸릴 수 있어요.</span></div></div><form class="composer" @submit.prevent="send"><div v-if="turns>=20" class="limit-note">20턴을 마쳤어요. 상담을 종료하고 평가받아 보세요.</div><textarea v-model="draft" placeholder="상담사로서 고객에게 답변해 보세요…" maxlength="2000" rows="3" :disabled="locked||turns>=20||session.status!=='active'" @keydown.ctrl.enter.prevent="send" @keydown.meta.enter.prevent="send" aria-label="상담사 답변"></textarea><div class="composer-footer"><span>Ctrl / ⌘ + Enter로 전송 · {{draft.length}}/2000</span><button v-if="sending" type="button" class="stop-btn" @click="controller?.abort()"><Square :size="13"/>중단</button><button v-else type="submit" class="send-btn" :disabled="locked||!draft.trim()||turns>=20"><Send :size="16"/>전송</button></div></form></div>
        <aside class="evidence-panel panel"><div class="evidence-title"><BookOpen :size="19"/><div><h3>업무 자료</h3><p>조회 기록은 평가에 반영돼요.</p></div></div><div class="document-tabs"><button v-for="t in tabs" :key="t.key" :class="{active:activeTab===t.key}" @click="activeTab=t.key" :disabled="locked">{{t.label}}<span v-if="documents[t.key]" class="tiny-dot"></span></button></div><div class="document-body"><form v-if="activeTab==='policy'" class="policy-search" @submit.prevent="searchPolicy"><label for="policy-query">상황에 맞는 정책 검색</label><textarea id="policy-query" v-model="policyQuery" placeholder="예: 출고 전 취소와 배송 지연 보상" maxlength="4000" rows="3" :disabled="locked"></textarea><button class="secondary" :disabled="locked||!policyQuery.trim()"><Search :size="15"/>관련 정책 검색</button><small v-if="retrieved">{{retrieved.embedding_mode==='openai'?'의미 검색':'데모 검색 · 품질 측정용 아님'}} · {{retrieved.hits.length}}개 / {{retrieved.corpus_size}}개 정책</small></form><div v-if="!documents[activeTab]" class="document-empty"><component :is="tabs.find(x=>x.key===activeTab).icon" :size="35"/><strong>{{tabs.find(x=>x.key===activeTab).label}}을 확인해 보세요.</strong><p>정보를 직접 확인한 뒤<br>고객에게 정확하게 안내하세요.</p><button class="secondary" @click="loadDoc(activeTab)" :disabled="locked"><Search :size="15"/>자료 조회하기</button></div><template v-else-if="activeTab==='order'"><div class="verified"><CheckCircle2 :size="15"/>주문 조회 완료</div><div class="order-product">{{documents.order.product}}</div><span class="order-id">{{documents.order.id}}</span><dl class="order-details"><template v-for="(v,k) in documents.order" :key="k"><template v-if="!['id','product'].includes(k)"><dt>{{({amount:'주문 금액',status:'주문 상태',promised_shipping:'약속 출고일',reference_date:'훈련 기준일',shipping_delay_days:'출고 지연일',shipping_fee:'배송비',received_date:'수령일',days_since_received:'수령 후 경과일'})[k]||k}}</dt><dd>{{['amount','shipping_fee'].includes(k)?Number(v).toLocaleString()+'원':['shipping_delay_days','days_since_received'].includes(k)?v+'일':v}}</dd></template></template></dl><p class="document-note">재도전에서도 같은 기준일과 주문 상태를 사용합니다.</p></template><template v-else-if="activeTab==='history'"><div class="verified"><CheckCircle2 :size="15"/>이전 상담 조회 완료</div><article v-for="h in documents.history" :key="h.id" class="history-note"><span>{{h.date}} · {{h.agent}}</span><p>{{h.text}}</p><small>{{h.id}}</small></article></template><template v-else><div class="verified"><CheckCircle2 :size="15"/>회사 정책 조회 완료</div><article v-for="p in policyList" :key="p.id" class="policy-note"><span>{{p.id}}</span><h4>{{p.title}}</h4><p>{{p.text}}</p><small v-if="p.distance!==undefined">거리 {{p.distance}} · 정확도 점수가 아닙니다</small></article></template></div></aside>
      </div>
    </section>

    <section v-else-if="view==='report'&&report&&session" class="page report-page">
      <div class="page-heading"><div><div class="eyebrow">YOUR REHEARSAL REPORT</div><h1>이번 연습이, 다음 응대를 바꿔요.</h1><p>{{session.title}} · {{fmtDate(session.created_at)}}</p></div><button class="primary" @click="retry" :disabled="locked"><RefreshCw :size="17"/>같은 상황에 재도전</button></div>
      <div class="report-summary"><div class="score-ring" :style="{'--score':report.total+'%'}"><div><strong>{{report.total}}</strong><span>/ 100</span></div></div><div class="report-summary-copy"><span class="eyebrow">{{report.is_demo?'규칙 기반 데모 평가':'근거 기반 상담 피드백'}}</span><h2>{{report.total>=80?'잘 해냈어요. 구체성을 더해 볼까요?':report.total>=60?'좋은 출발이에요. 한 단계 더 연습해요.':'확인부터 차근차근, 다시 도전해 봐요.'}}</h2><p>{{report.summary}}</p><div class="report-tags"><span>{{session.rubric_version}}</span><span>{{session.scenario_version}}</span><span>{{report.is_demo?'DEMO':session.model}}</span></div></div></div>
      <div v-if="comparison" class="comparison-card"><div><TrendingUp :size="22"/><strong>이전 도전과 비교</strong><span>같은 상황 · 같은 평가 기준</span></div><div class="comparison-total">{{comparison.previous_total}} <ArrowRight :size="19"/> <strong>{{comparison.current_total}}점</strong><span :class="['delta',comparison.delta>=0?'positive':'negative']">{{delta(comparison.delta)}}점</span></div><div class="comparison-criteria"><div v-for="c in comparison.criteria" :key="c.key"><span>{{labels[c.key]}}</span><strong>{{c.before}} → {{c.after}} <small :class="c.delta>=0?'positive':'negative'">({{delta(c.delta)}})</small></strong></div></div><p>점수에는 모델 평가의 변동이 있을 수 있어요. 개선된 행동과 근거를 함께 확인하세요.</p></div>
      <details v-if="report.rag" class="panel transcript"><summary>평가에 사용한 정책 검색 근거</summary><p>{{report.rag.embedding_mode==='openai'?'OpenAI 임베딩 의미 검색':'데모 해시 검색 · 품질 평가 제외'}} · {{report.rag.embedding_model}}</p><p>{{report.rag.hits.map(x=>x.id).join(' · ')}}</p><p>{{report.rag.corpus_size}}개 문서 중 {{report.rag.hits.length}}개 검색 · {{(report.rag.elapsed_ms/1000).toFixed(2)}}초</p><p>검색된 정책의 관련성과 평가 이유를 함께 확인하세요. 검색 누락 시 평가도 영향을 받을 수 있습니다.</p><pre>{{report.rag.query}}</pre></details><div class="section-heading"><div><h2>항목별 피드백</h2><p>어떤 행동이 점수로 이어졌는지 확인해 보세요.</p></div><span class="muted">각 항목 25점</span></div>
      <div class="criteria-grid"><article v-for="(c,i) in report.criteria" :key="c.key" class="criterion-card"><div class="criterion-header"><span class="criterion-number">0{{i+1}}</span><h3>{{labels[c.key]}}</h3><strong>{{c.score}}<small>/25</small></strong></div><div class="score-bar"><span :style="{width:(c.score/25*100)+'%'}"></span></div><p>{{c.reason}}</p><div class="action-line"><Target :size="16"/><span>{{c.action}}</span></div><details class="evidence-details"><summary>판단 근거 {{c.evidence.length}}개 보기</summary><blockquote v-for="(e,j) in c.evidence" :key="j"><span>{{e.source_id}}</span><p>“{{e.quote}}”</p><details><summary>전체 근거 확인</summary><pre>{{report.sources[e.source_id]}}</pre></details></blockquote></details></article></div>
      <div class="coaching-grid"><article class="panel coaching-card"><span class="eyebrow">KEEP DOING</span><h3>잘한 점</h3><ul><li v-for="s in report.coaching.strengths" :key="s"><CheckCircle2 :size="17"/>{{s}}</li></ul></article><article class="panel coaching-card"><span class="eyebrow">NEXT PRACTICE</span><h3>다음 연습에서 해 볼 것</h3><ul><li v-for="s in report.coaching.next_actions" :key="s"><Target :size="17"/>{{s}}</li></ul></article></div>
      <div class="section-heading"><div><h2>이렇게 답해 보면 어때요?</h2><p>실제 내 발언을 바탕으로 다듬은 답변이에요.</p></div></div><article v-for="(r,i) in report.coaching.rewrites" :key="i" class="rewrite-card"><div class="rewrite-before"><span>내가 했던 답변</span><p>{{r.original}}</p></div><ArrowRight class="rewrite-arrow" :size="22"/><div class="rewrite-after"><span><Check :size="15"/>개선 답변</span><p>{{r.improved}}</p><small>{{r.reason}}</small></div></article>
      <details class="panel transcript"><summary>전체 상담 대화 다시 보기</summary><div v-for="m in session.messages" :key="m.id"><strong>{{m.role==='user'?'상담사':'AI 고객'}}</strong><p>{{m.content}}</p><small>{{m.id}}</small></div></details><div class="report-footer"><button class="secondary" @click="go('history')"><ArrowLeft :size="16"/>훈련 기록</button><button class="primary" @click="retry" :disabled="locked"><RefreshCw :size="16"/>피드백 적용해서 다시 연습하기</button></div>
    </section>

    <section v-else-if="view==='history'" class="page"><div class="page-heading"><div><div class="eyebrow">MY PRACTICE LOG</div><h1>연습의 기록, 성장의 근거.</h1><p>진행 중인 상담을 이어가거나 지난 리포트를 확인하세요. 최근 200개를 표시합니다.</p></div><button class="secondary" @click="refreshHistory().catch(e=>error=e.message)"><RefreshCw :size="16"/>새로고침</button></div><div v-if="!records.length" class="empty"><History :size="40"/><h3>아직 훈련 기록이 없어요.</h3><p>첫 상담을 연습하고 나만의 기록을 만들어 보세요.</p><button class="primary" @click="go('home')">시나리오 고르기 <ArrowRight :size="16"/></button></div><div v-else class="record-list"><button v-for="r in records" :key="r.id" class="record-row" @click="openRecord(r.id)" :disabled="locked"><div class="record-symbol"><MessagesSquare :size="20"/></div><div class="record-main"><strong>{{r.title}}</strong><small>{{fmtDate(r.created_at)}} · {{r.mode==='demo'?'데모':'AI 훈련'}}{{r.retry_of?' · 재도전':''}}</small></div><span :class="['status',r.status==='completed'?'complete':'']">{{r.status==='completed'?'평가 완료':r.status==='evaluating'?'평가 중':'진행 중'}}</span><strong class="record-score">{{r.total===null?'—':r.total+'점'}}</strong><ChevronRight :size="17"/></button></div></section>

    <section v-else-if="view==='admin'" class="page admin-page"><div class="page-heading"><div><div class="eyebrow">TRAINING OPERATIONS</div><h1>훈련 운영 현황</h1><p>상담 결과와 실행 오류를 살펴보고, LangSmith에서 에이전트 호출을 추적하세요.</p></div></div><form class="admin-login panel" @submit.prevent="loadAdmin"><ShieldCheck :size="22"/><label>관리자 코드<input v-model="adminToken" type="password" placeholder="관리자 코드 입력" autocomplete="off"/></label><button class="primary" :disabled="adminLoading"><LoaderCircle v-if="adminLoading" class="spin" :size="16"/>{{admin?'새로고침':'현황 확인'}}</button></form><template v-if="admin"><div class="stats-row admin-stats"><div class="stat-card"><span>전체 훈련</span><strong>{{admin.stats.sessions}}</strong></div><div class="stat-card"><span>완료한 훈련</span><strong>{{admin.stats.completed}}</strong></div><div class="stat-card"><span>평균 점수</span><strong>{{admin.stats.average}}</strong></div><div class="stat-card"><span>최근 실행 오류</span><strong>{{admin.stats.errors}}</strong></div></div><div class="langsmith-card panel"><div><h3>LangSmith 실행 추적</h3><p>{{admin.tracing?'추적 활성화':'추적 비활성화'}} · 프로젝트: {{admin.project}}</p><p class="muted">실행 ID 또는 session_id 메타데이터로 검색하세요. 토큰 수는 대화·평가·코칭 모델의 실제 사용량입니다. 임베딩 사용량은 리포트 검색 기록에 별도로 저장합니다.</p></div><a :href="admin.langsmith_url" target="_blank" rel="noopener" class="secondary">LangSmith 열기 <ExternalLink :size="15"/></a></div><div class="section-heading"><h2>최근 실행 기록</h2><span class="muted">최근 100개 · 대화/평가 구분</span></div><div class="table-wrap"><table><thead><tr><th>실행</th><th>상태</th><th>소요 시간</th><th>사용 토큰</th><th>실행 ID / 상담 ID</th><th>오류</th></tr></thead><tbody><tr v-for="r in admin.runs" :key="r.id"><td><strong>{{r.kind==='customer'?'고객 응답':'평가·코칭'}}</strong><small>{{fmtDate(r.created_at)}} · {{r.mode}}</small></td><td><span :class="['status',r.status==='success'?'complete':'']">{{r.status}}</span></td><td>{{r.elapsed_ms===null?'—':(r.elapsed_ms/1000).toFixed(1)+'초'}}</td><td>{{Object.keys(r.usage).length?Object.values(r.usage).reduce((s,x)=>s+(x.total_tokens||0),0).toLocaleString():'—'}}</td><td class="ids"><code>{{r.id}}</code><button @click="openRecord(r.session_id)">{{r.session_id}}</button></td><td>{{r.error||'—'}}</td></tr><tr v-if="!admin.runs.length"><td colspan="6" class="empty-cell">아직 실행 기록이 없습니다.</td></tr></tbody></table></div><div class="section-heading"><h2>상담 결과</h2></div><div class="record-list"><button v-for="r in admin.sessions" :key="r.id" class="record-row" @click="openRecord(r.id)"><div class="record-main"><strong>{{r.title}}</strong><small>{{fmtDate(r.created_at)}} · {{r.mode}}</small></div><span class="status">{{r.status}}</span><strong class="record-score">{{r.total===null?'—':r.total+'점'}}</strong><ChevronRight :size="16"/></button></div></template><p v-else class="admin-help">관리자 코드는 backend/.env의 ADMIN_TOKEN 값입니다. 기본값은 실행 안내 문서를 확인하세요.</p></section>
    <footer v-if="view!=='training'" class="global-footer"><span>응대 리허설</span> 작은 연습이 만드는, 더 나은 고객 경험.</footer>
  </main>
</div>
</template>
